arguments.argument:
with(obj_cei)
{

var vb_choose;

vb_choose=show_message_ext("변경할 방향을선택하세요　　", "↑변경", "", "↓변경")

if vb_choose=1
{
up[obj_choose.chooses, 0]=get_integer("↑속도", up[obj_choose.chooses, 0])
if up[obj_choose.chooses, 0]>255{up[obj_choose.chooses, 0]=255}

for(i=0; i!=max_d; i+=1)
{
up[obj_choose.chooses, i]=up[obj_choose.chooses, 0]
down[obj_choose.chooses, i]=0
}
}
else
{
down[obj_choose.chooses, 0]=get_integer("↓속도", down[obj_choose.chooses, 0])
if down[obj_choose.chooses, 0]>255{down[obj_choose.chooses, 0]=255}

for(i=0; i!=max_d; i+=1)
{
down[obj_choose.chooses, i]=down[obj_choose.chooses, 0]
up[obj_choose.chooses, i]=0
}
}

vb_choose=show_message_ext("변경할 방향을선택하세요　　", "←변경", "", "→변경")

if vb_choose=3
{
right[obj_choose.chooses, 0]=get_integer("→속도", right[obj_choose.chooses, 0])
if right[obj_choose.chooses, 0]>255{right[obj_choose.chooses, 0]=255}

for(i=0; i!=max_d; i+=1)
{
right[obj_choose.chooses, i]=right[obj_choose.chooses, 0]
left[obj_choose.chooses, i]=0
}
}
else
{
left[obj_choose.chooses, 0]=get_integer("←속도", left[obj_choose.chooses, 0])
if left[obj_choose.chooses, 0]>255{left[obj_choose.chooses, 0]=255}

for(i=0; i!=max_d; i+=1)
{
left[obj_choose.chooses, i]=left[obj_choose.chooses, 0]
right[obj_choose.chooses, i]=0
}
}

alarm[0]=10
}
